node -e "
const fs = require('fs');
const zlib = require('zlib');
const { execSync } = require('child_process');

// .docx is a ZIP file. We'll use Node's built-in 'unzip' approach via child process or manual ZIP parsing.
// Let's try a minimal ZIP parser using the buffer.

const buf = fs.readFileSync('/workspace/testbed/docs/Meeting_Notes_2024_06.docx');

// Find all local file headers (PK\x03\x04)
// But easier: find Central Directory entries and use them.
// Let's find End of Central Directory record first.

// Find EOCD signature: PK\x05\x06
let eocdOffset = -1;
for (let i = buf.length - 22; i >= 0; i--) {
  if (buf[i] === 0x50 && buf[i+1] === 0x4b && buf[i+2] === 0x05 && buf[i+3] === 0x06) {
    eocdOffset = i;
    break;
  }
}

const cdOffset = buf.readUInt32LE(eocdOffset + 16);
const cdSize = buf.readUInt32LE(eocdOffset + 12);
const cdCount = buf.readUInt16LE(eocdOffset + 10);

// Parse central directory entries to find word/document.xml
let pos = cdOffset;
let targetOffset = -1;
let targetCompSize = 0;
let targetUncompSize = 0;
let targetMethod = 0;

for (let i = 0; i < cdCount; i++) {
  const sig = buf.readUInt32LE(pos);
  if (sig !== 0x02014b50) break;
  const method = buf.readUInt16LE(pos + 10);
  const compSize = buf.readUInt32LE(pos + 20);
  const uncompSize = buf.readUInt32LE(pos + 24);
  const nameLen = buf.readUInt16LE(pos + 28);
  const extraLen = buf.readUInt16LE(pos + 30);
  const commentLen = buf.readUInt16LE(pos + 32);
  const localHeaderOffset = buf.readUInt32LE(pos + 42);
  const name = buf.toString('utf8', pos + 46, pos + 46 + nameLen);

  if (name === 'word/document.xml') {
    targetOffset = localHeaderOffset;
    targetCompSize = compSize;
    targetUncompSize = uncompSize;
    targetMethod = method;
  }

  pos += 46 + nameLen + extraLen + commentLen;
}

if (targetOffset === -1) {
  console.error('word/document.xml not found in archive');
  process.exit(1);
}

// Read local file header to get to the data
const localNameLen = buf.readUInt16LE(targetOffset + 26);
const localExtraLen = buf.readUInt16LE(targetOffset + 28);
const dataStart = targetOffset + 30 + localNameLen + localExtraLen;
const compData = buf.slice(dataStart, dataStart + targetCompSize);

let xml;
if (targetMethod === 0) {
  xml = compData.toString('utf8');
} else {
  // Deflate (method 8) — use inflateRawSync
  xml = zlib.inflateRawSync(compData).toString('utf8');
}

// Extract paragraph text from XML
// Paragraphs are <w:p>...</w:p>, text runs are <w:t>...</w:t>
const paragraphs = [];
const pRegex = /<w:p[ >][\s\S]*?<\/w:p>/g;
const tRegex = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;

let pMatch;
while ((pMatch = pRegex.exec(xml)) !== null) {
  const pXml = pMatch[0];
  let text = '';
  let tMatch;
  tRegex.lastIndex = 0;
  while ((tMatch = tRegex.exec(pXml)) !== null) {
    text += tMatch[1];
  }
  if (text.trim()) {
    paragraphs.push(text);
  }
}

const output = paragraphs.join('\n\n');
console.log(output);
" 2>&1
